=== FILE: axil_timer.v ===
// axil_timer: AXI4-Lite 32-bit down-counting timer with one-shot and
// periodic modes and a level interrupt.
// Implements interface_spec.md per microarchitecture.md.

module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,

    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,

    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,

    output reg  [1:0]            s_axil_bresp,
    output reg                   s_axil_bvalid,
    input  wire                  s_axil_bready,

    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,

    output reg  [31:0]           s_axil_rdata,
    output reg  [1:0]            s_axil_rresp,
    output reg                   s_axil_rvalid,
    input  wire                  s_axil_rready,

    output wire                  irq
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    localparam [1:0] IDX_CTRL   = 2'd0;
    localparam [1:0] IDX_LOAD   = 2'd1;
    localparam [1:0] IDX_COUNT  = 2'd2;
    localparam [1:0] IDX_STATUS = 2'd3;

    // ------------------------------------------------------------------
    // Channel state
    // ------------------------------------------------------------------
    reg                  aw_held;
    reg                  w_held;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg [31:0]           w_data_q;
    reg [3:0]            w_strb_q;

    // ------------------------------------------------------------------
    // Timer state
    // ------------------------------------------------------------------
    reg        en;
    reg        ie;
    reg        mode;
    reg        expired;
    reg [31:0] load;
    reg [31:0] count;

    assign s_axil_awready = !aw_held && !s_axil_bvalid;
    assign s_axil_wready  = !w_held  && !s_axil_bvalid;
    assign s_axil_arready = !s_axil_rvalid;

    wire aw_hs    = s_axil_awvalid && s_axil_awready;
    wire w_hs     = s_axil_wvalid  && s_axil_wready;
    wire ar_hs    = s_axil_arvalid && s_axil_arready;
    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [31:0]           wr_data = w_held  ? w_data_q  : s_axil_wdata;
    wire [3:0]            wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

    // Mapped: word aligned and below 0x10 (no aliasing at wider addresses).
    wire       wr_mapped = (wr_addr[1:0] == 2'b00) &&
                           ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
    wire [1:0] wr_idx    = wr_addr[3:2];
    wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                           ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});
    wire [1:0] rd_idx    = s_axil_araddr[3:2];

    wire wr_ok    = wr_mapped && (wr_idx != IDX_COUNT);
    wire wr_ctrl  = do_write && wr_mapped && (wr_idx == IDX_CTRL) && wr_strb[0];
    wire wr_load  = do_write && wr_mapped && (wr_idx == IDX_LOAD);
    wire wr_clear = do_write && wr_mapped && (wr_idx == IDX_STATUS) &&
                    wr_strb[0] && wr_data[0];

    // Last cycle of a count; a count of 0 is treated like 1.
    wire count_end = en && (count <= 32'd1);

    assign irq = expired && ie;

    // ------------------------------------------------------------------
    // Write channels
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held       <= 1'b0;
            w_held        <= 1'b0;
            s_axil_bvalid <= 1'b0;
            s_axil_bresp  <= RESP_OKAY;
        end else if (do_write) begin
            aw_held       <= 1'b0;
            w_held        <= 1'b0;
            s_axil_bvalid <= 1'b1;
            s_axil_bresp  <= wr_ok ? RESP_OKAY : RESP_SLVERR;
        end else begin
            if (aw_hs)
                aw_held <= 1'b1;
            if (w_hs)
                w_held <= 1'b1;
            if (s_axil_bvalid && s_axil_bready)
                s_axil_bvalid <= 1'b0;
        end
    end

    // Held address and data: read only while a holding flag is set.
    always @(posedge aclk) begin
        if (aw_hs)
            aw_addr_q <= s_axil_awaddr;
        if (w_hs) begin
            w_data_q <= s_axil_wdata;
            w_strb_q <= s_axil_wstrb;
        end
    end

    // ------------------------------------------------------------------
    // Read channel
    // ------------------------------------------------------------------
    reg [31:0] rd_value;

    always @(*) begin
        rd_value = 32'd0;
        if (rd_mapped) begin
            case (rd_idx)
                IDX_CTRL:   rd_value = {29'd0, mode, ie, en};
                IDX_LOAD:   rd_value = load;
                IDX_COUNT:  rd_value = count;
                IDX_STATUS: rd_value = {31'd0, expired};
                default:    rd_value = 32'd0;
            endcase
        end
    end

    always @(posedge aclk) begin
        if (!aresetn) begin
            s_axil_rvalid <= 1'b0;
            s_axil_rdata  <= 32'd0;
            s_axil_rresp  <= RESP_OKAY;
        end else if (ar_hs) begin
            s_axil_rvalid <= 1'b1;
            s_axil_rdata  <= rd_value;
            s_axil_rresp  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
        end else if (s_axil_rvalid && s_axil_rready) begin
            s_axil_rvalid <= 1'b0;
        end
    end

    // ------------------------------------------------------------------
    // Timer. Order gives the specified priorities (last assignment wins):
    // 1 count step, 2 expired clear then set, 3 CTRL write, 4 LOAD write.
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            en      <= 1'b0;
            ie      <= 1'b0;
            mode    <= 1'b0;
            expired <= 1'b0;
            load    <= 32'd0;
            count   <= 32'd0;
        end else begin
            // 1. Count step.
            if (count_end) begin
                if (mode) begin
                    count <= load;
                end else begin
                    count <= 32'd0;
                    en    <= 1'b0;
                end
            end else if (en) begin
                count <= count - 32'd1;
            end

            // 2. Expiry: a count end beats a clear.
            if (wr_clear)
                expired <= 1'b0;
            if (count_end)
                expired <= 1'b1;

            // 3. CTRL write wins over the count step for en and count.
            if (wr_ctrl) begin
                ie   <= wr_data[1];
                mode <= wr_data[2];
                en   <= wr_data[0];
                if (wr_data[0])
                    count <= load;
            end

            // 4. LOAD byte merge.
            if (wr_load) begin
                if (wr_strb[0]) load[7:0]   <= wr_data[7:0];
                if (wr_strb[1]) load[15:8]  <= wr_data[15:8];
                if (wr_strb[2]) load[23:16] <= wr_data[23:16];
                if (wr_strb[3]) load[31:24] <= wr_data[31:24];
            end
        end
    end

`ifdef FORMAL
    // Design-intent assertions (not a full proof).
    reg f_rst_seen = 1'b0;
    always @(posedge aclk)
        if (!aresetn)
            f_rst_seen <= 1'b1;

    always @(*) begin
        if (f_rst_seen && aresetn) begin
            assert(!(aw_held && w_held));
            if (s_axil_bvalid)
                assert(!aw_held && !w_held);
            if (!en)
                assert(!count_end);
            assert(irq == (expired && ie));
        end
    end
`endif

endmodule
=== END FILE ===
=== FILE: axil_timer_tb.v ===
// axil_timer_tb: self-checking testbench for axil_timer.
// Two lanes: dut4 (ADDR_WIDTH 4) and dut8 (ADDR_WIDTH 8), selected by `lane`.

module axil_timer_tb;

    localparam [7:0] A_CTRL   = 8'h00;
    localparam [7:0] A_LOAD   = 8'h04;
    localparam [7:0] A_COUNT  = 8'h08;
    localparam [7:0] A_STATUS = 8'h0C;
    localparam [1:0] OKAY     = 2'b00;
    localparam [1:0] SLVERR   = 2'b10;

    reg clk = 1'b0;
    always #5 clk = ~clk;

    reg aresetn = 1'b0;
    reg lane    = 1'b0;

    reg  [7:0]  awaddr  = 8'd0;
    reg         awvalid = 1'b0;
    reg  [31:0] wdata   = 32'd0;
    reg  [3:0]  wstrb   = 4'd0;
    reg         wvalid  = 1'b0;
    reg         bready  = 1'b0;
    reg  [7:0]  araddr  = 8'd0;
    reg         arvalid = 1'b0;
    reg         rready  = 1'b0;

    wire        awready4, wready4, bvalid4, arready4, rvalid4, irq4;
    wire [1:0]  bresp4, rresp4;
    wire [31:0] rdata4;
    wire        awready8, wready8, bvalid8, arready8, rvalid8, irq8;
    wire [1:0]  bresp8, rresp8;
    wire [31:0] rdata8;

    axil_timer #(.ADDR_WIDTH(4)) dut4 (
        .aclk(clk), .aresetn(aresetn),
        .s_axil_awaddr(awaddr[3:0]), .s_axil_awvalid(awvalid && !lane), .s_axil_awready(awready4),
        .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid && !lane), .s_axil_wready(wready4),
        .s_axil_bresp(bresp4), .s_axil_bvalid(bvalid4), .s_axil_bready(bready && !lane),
        .s_axil_araddr(araddr[3:0]), .s_axil_arvalid(arvalid && !lane), .s_axil_arready(arready4),
        .s_axil_rdata(rdata4), .s_axil_rresp(rresp4), .s_axil_rvalid(rvalid4), .s_axil_rready(rready && !lane),
        .irq(irq4)
    );

    axil_timer #(.ADDR_WIDTH(8)) dut8 (
        .aclk(clk), .aresetn(aresetn),
        .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid && lane), .s_axil_awready(awready8),
        .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid && lane), .s_axil_wready(wready8),
        .s_axil_bresp(bresp8), .s_axil_bvalid(bvalid8), .s_axil_bready(bready && lane),
        .s_axil_araddr(araddr), .s_axil_arvalid(arvalid && lane), .s_axil_arready(arready8),
        .s_axil_rdata(rdata8), .s_axil_rresp(rresp8), .s_axil_rvalid(rvalid8), .s_axil_rready(rready && lane),
        .irq(irq8)
    );

    wire        awready = lane ? awready8 : awready4;
    wire        wready  = lane ? wready8  : wready4;
    wire        bvalid  = lane ? bvalid8  : bvalid4;
    wire [1:0]  bresp   = lane ? bresp8   : bresp4;
    wire        arready = lane ? arready8 : arready4;
    wire        rvalid  = lane ? rvalid8  : rvalid4;
    wire [31:0] rdata   = lane ? rdata8   : rdata4;
    wire [1:0]  rresp   = lane ? rresp8   : rresp4;
    wire        irq     = lane ? irq8     : irq4;

    // Rising-edge counter: read at a negedge, it is the index of the last edge.
    integer edge_cnt = 0;
    always @(posedge clk) edge_cnt <= edge_cnt + 1;

    // Interrupt rise monitor.
    reg     irq_prev      = 1'b0;
    integer irq_rises     = 0;
    integer irq_rise_edge = -1;
    always @(negedge clk) begin
        if (irq && !irq_prev) begin
            irq_rises     = irq_rises + 1;
            irq_rise_edge = edge_cnt;
        end
        irq_prev = irq;
    end

    integer passed = 0;
    integer failed = 0;
    reg [8*64-1:0] nonce;

    task check;
        input          cond;
        input [8*64-1:0] msg;
        begin
            if (cond)
                passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("AW%0d: %0s", lane ? 8 : 4, msg);
            end
        end
    endtask

    task check_eq;
        input [31:0]     got;
        input [31:0]     exp;
        input [8*64-1:0] msg;
        begin
            if (got === exp)
                passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("AW%0d: %0s: got 0x%08h, expected 0x%08h", lane ? 8 : 4, msg, got, exp);
            end
        end
    endtask

    // ------------------------------------------------------------------
    // Bus tasks. Each starts and ends at a negedge.
    // ------------------------------------------------------------------
    integer    last_eff_edge;
    reg [1:0]  last_bresp;
    integer    last_ar_edge;
    reg [31:0] last_rdata;
    reg [1:0]  last_rresp;

    // order: 0 address and data together, 1 address first, 2 data first.
    task axi_write;
        input [7:0]  addr;
        input [31:0] data;
        input [3:0]  strb;
        input integer order;
        input integer bdelay;
        reg aw_d, w_d, aw_f, w_f;
        integer guard, k;
        begin
            aw_d = 1'b0;
            w_d  = 1'b0;
            if (order != 2) begin awaddr = addr; awvalid = 1'b1; end
            if (order != 1) begin wdata = data; wstrb = strb; wvalid = 1'b1; end
            guard = 0;
            while (!(aw_d && w_d) && guard < 32) begin
                aw_f = awvalid && awready;
                w_f  = wvalid && wready;
                @(negedge clk);
                guard = guard + 1;
                if (aw_f) begin aw_d = 1'b1; awvalid = 1'b0; end
                if (w_f)  begin w_d  = 1'b1; wvalid  = 1'b0; end
                if (order == 1 && aw_d && !w_d && !wvalid) begin
                    check(!awready, "AWREADY low while the address is held");
                    check(wready, "WREADY high while only the address is held");
                    wdata = data; wstrb = strb; wvalid = 1'b1;
                end
                if (order == 2 && w_d && !aw_d && !awvalid) begin
                    check(!wready, "WREADY low while the data is held");
                    check(awready, "AWREADY high while only the data is held");
                    awaddr = addr; awvalid = 1'b1;
                end
            end
            awvalid = 1'b0;
            wvalid  = 1'b0;
            check(aw_d && w_d, "write handshake completes");
            check(bvalid, "BVALID high on the edge after the write");
            last_eff_edge = edge_cnt;
            last_bresp    = bresp;
            for (k = 0; k < bdelay; k = k + 1) begin
                @(negedge clk);
                check(bvalid && bresp == last_bresp, "BVALID and BRESP held under backpressure");
                check(!awready && !wready, "no write accepted while BVALID waits");
            end
            bready = 1'b1;
            @(negedge clk);
            bready = 1'b0;
            check(!bvalid, "BVALID drops after BREADY");
        end
    endtask

    task axi_read;
        input [7:0]   addr;
        input integer rdelay;
        integer guard, k;
        begin
            araddr  = addr;
            arvalid = 1'b1;
            guard   = 0;
            while (!arready && guard < 32) begin
                @(negedge clk);
                guard = guard + 1;
            end
            check(arready, "ARREADY high for a new read");
            @(negedge clk);
            arvalid      = 1'b0;
            last_ar_edge = edge_cnt;
            check(rvalid, "RVALID high on the edge after the address");
            last_rdata = rdata;
            last_rresp = rresp;
            for (k = 0; k < rdelay; k = k + 1) begin
                @(negedge clk);
                check(rvalid && rdata == last_rdata && rresp == last_rresp,
                      "RVALID, RDATA, RRESP held under backpressure");
                check(!arready, "ARREADY low while a read response waits");
            end
            rready = 1'b1;
            @(negedge clk);
            rready = 1'b0;
            check(!rvalid, "RVALID drops after RREADY");
        end
    endtask

    task read_expect;
        input [7:0]      addr;
        input [31:0]     exp;
        input [1:0]      exp_resp;
        input [8*64-1:0] msg;
        begin
            axi_read(addr, 0);
            check_eq(last_rdata, exp, msg);
            check_eq({30'd0, last_rresp}, {30'd0, exp_resp}, msg);
        end
    endtask

    task write_expect;
        input [7:0]      addr;
        input [31:0]     data;
        input [3:0]      strb;
        input integer    order;
        input integer    bdelay;
        input [1:0]      exp_resp;
        input [8*64-1:0] msg;
        begin
            axi_write(addr, data, strb, order, bdelay);
            check_eq({30'd0, last_bresp}, {30'd0, exp_resp}, msg);
        end
    endtask

    task wait_until_edge;
        input integer n;
        begin
            while (edge_cnt < n) @(negedge clk);
            check(edge_cnt == n, "test schedule reached the intended edge");
        end
    endtask

    task do_reset;
        input new_lane;
        begin
            aresetn = 1'b0;
            awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0;
            bready  = 1'b0; rready = 1'b0;
            @(negedge clk);
            lane = new_lane;
            @(negedge clk);
            @(negedge clk);
            aresetn = 1'b1;
            @(negedge clk);
        end
    endtask

    // ------------------------------------------------------------------
    // The test sequence, run once per lane.
    // ------------------------------------------------------------------
    integer    t0, t1, r0, i;
    reg [31:0] cnt_a;

    task run_lane;
        begin
            // --- Reset values ---
            check(awready && wready && arready, "ready signals high after reset");
            check(!bvalid && !rvalid, "no responses pending after reset");
            check(!irq, "irq low after reset");
            read_expect(A_CTRL,   32'd0, OKAY, "CTRL reset value");
            read_expect(A_LOAD,   32'd0, OKAY, "LOAD reset value");
            read_expect(A_COUNT,  32'd0, OKAY, "COUNT reset value");
            read_expect(A_STATUS, 32'd0, OKAY, "STATUS reset value");

            // --- LOAD with partial strobes, channel orders, backpressure ---
            write_expect(A_LOAD, 32'hFFFF_FFFF, 4'b1111, 0, 0, OKAY, "LOAD full write");
            read_expect(A_LOAD, 32'hFFFF_FFFF, OKAY, "LOAD full readback");
            write_expect(A_LOAD, 32'h1234_5678, 4'b0101, 1, 2, OKAY, "LOAD strb 0101, address first");
            read_expect(A_LOAD, 32'hFF34_FF78, OKAY, "LOAD after strb 0101");
            write_expect(A_LOAD, 32'hAABB_CCDD, 4'b1010, 2, 3, OKAY, "LOAD strb 1010, data first");
            read_expect(A_LOAD, 32'hAA34_CC78, OKAY, "LOAD after strb 1010");
            write_expect(A_LOAD, 32'h0000_0000, 4'b0000, 0, 1, OKAY, "LOAD write with no strobes");
            axi_read(A_LOAD, 4);
            check_eq(last_rdata, 32'hAA34_CC78, "LOAD unchanged, read under backpressure");

            // --- COUNT read only, SLVERR policy ---
            write_expect(A_COUNT, 32'h0000_0055, 4'b1111, 0, 0, SLVERR, "COUNT write gets SLVERR");
            read_expect(A_COUNT, 32'd0, OKAY, "COUNT unchanged by a write");
            write_expect(8'h05, 32'h1111_1111, 4'b1111, 1, 0, SLVERR, "unaligned write 0x5 gets SLVERR");
            write_expect(8'h06, 32'h2222_2222, 4'b1111, 2, 0, SLVERR, "unaligned write 0x6 gets SLVERR");
            write_expect(8'h01, 32'h0000_0003, 4'b1111, 0, 0, SLVERR, "unaligned write 0x1 gets SLVERR");
            read_expect(A_LOAD, 32'hAA34_CC78, OKAY, "LOAD untouched by unaligned writes");
            read_expect(A_CTRL, 32'd0, OKAY, "CTRL untouched by unaligned writes");
            read_expect(8'h06, 32'd0, SLVERR, "unaligned read 0x6");
            read_expect(8'h01, 32'd0, SLVERR, "unaligned read 0x1");
            read_expect(8'h0D, 32'd0, SLVERR, "unaligned read 0xD");
            if (lane) begin
                write_expect(8'h14, 32'h0BAD_0BAD, 4'b1111, 0, 0, SLVERR, "write 0x14 gets SLVERR");
                write_expect(8'h10, 32'h0000_0007, 4'b1111, 1, 0, SLVERR, "write 0x10 gets SLVERR");
                write_expect(8'hFC, 32'h0000_0001, 4'b1111, 2, 0, SLVERR, "write 0xFC gets SLVERR");
                read_expect(A_LOAD, 32'hAA34_CC78, OKAY, "LOAD not aliased from 0x14");
                read_expect(A_CTRL, 32'd0, OKAY, "CTRL not aliased from 0x10");
                read_expect(8'h10, 32'd0, SLVERR, "read 0x10 is zero with SLVERR");
                read_expect(8'h14, 32'd0, SLVERR, "read 0x14 is zero with SLVERR");
                read_expect(8'h18, 32'd0, SLVERR, "read 0x18 is zero with SLVERR");
                read_expect(8'hF4, 32'd0, SLVERR, "read 0xF4 is zero with SLVERR");
            end
            write_expect(A_STATUS, 32'h0000_0001, 4'b1111, 0, 0, OKAY, "STATUS write answers OKAY");

            // --- CTRL write without wstrb[0]; upper bits read zero ---
            write_expect(A_CTRL, 32'h0000_0007, 4'b1110, 0, 0, OKAY, "CTRL without wstrb[0] is OKAY");
            read_expect(A_CTRL, 32'd0, OKAY, "CTRL unchanged without wstrb[0]");
            read_expect(A_COUNT, 32'd0, OKAY, "no count started without wstrb[0]");
            write_expect(A_CTRL, 32'hFFFF_FFF8, 4'b1111, 0, 0, OKAY, "CTRL write of upper bits");
            read_expect(A_CTRL, 32'd0, OKAY, "CTRL bits 31:3 read as zero");

            // --- One-shot, timed to the cycle ---
            write_expect(A_LOAD, 32'd6, 4'b1111, 0, 0, OKAY, "LOAD 6");
            r0 = irq_rises;
            axi_write(A_CTRL, 32'h0000_0003, 4'b1111, 0, 0);
            t0 = last_eff_edge;
            axi_read(A_COUNT, 0);
            check_eq(last_rdata, 6 - (last_ar_edge - 1 - t0), "COUNT down by one per edge");
            wait_until_edge(t0 + 9);
            check_eq(irq_rises - r0, 1, "one interrupt for a one-shot count");
            check_eq(irq_rise_edge, t0 + 6, "one-shot LOAD 6 ends on edge E+6");
            read_expect(A_CTRL, 32'h0000_0002, OKAY, "EN clears itself after one-shot");
            read_expect(A_COUNT, 32'd0, OKAY, "COUNT 0 after one-shot");
            read_expect(A_STATUS, 32'd1, OKAY, "EXPIRED set after one-shot");
            check(irq, "irq held while EXPIRED and IE");
            write_expect(A_STATUS, 32'h0000_0000, 4'b1111, 0, 0, OKAY, "STATUS write of 0");
            read_expect(A_STATUS, 32'd1, OKAY, "EXPIRED kept by a write of 0");
            write_expect(A_STATUS, 32'h0000_0001, 4'b1110, 0, 0, OKAY, "STATUS write without wstrb[0]");
            read_expect(A_STATUS, 32'd1, OKAY, "EXPIRED kept without wstrb[0]");
            write_expect(A_STATUS, 32'h0000_0001, 4'b1111, 0, 0, OKAY, "STATUS clear");
            check(!irq, "irq drops on clear");
            read_expect(A_STATUS, 32'd0, OKAY, "EXPIRED cleared");
            repeat (30) @(negedge clk);
            check_eq(irq_rises - r0, 1, "no second interrupt after one-shot");
            read_expect(A_COUNT, 32'd0, OKAY, "COUNT stays 0 after one-shot");

            // --- One-shot with LOAD 1 and LOAD 0 (both one cycle) ---
            for (i = 1; i >= 0; i = i - 1) begin
                write_expect(A_LOAD, i, 4'b1111, 0, 0, OKAY, "LOAD 1 or 0");
                r0 = irq_rises;
                axi_write(A_CTRL, 32'h0000_0003, 4'b1111, 0, 0);
                t0 = last_eff_edge;
                wait_until_edge(t0 + 4);
                check_eq(irq_rises - r0, 1, "one interrupt for a short count");
                check_eq(irq_rise_edge, t0 + 1, "LOAD 1 or 0 ends on edge E+1");
                read_expect(A_CTRL, 32'h0000_0002, OKAY, "EN clears after short count");
                write_expect(A_STATUS, 32'h0000_0001, 4'b1111, 0, 0, OKAY, "STATUS clear");
            end

            // --- Interrupt enable on a pending expiry ---
            write_expect(A_LOAD, 32'd3, 4'b1111, 0, 0, OKAY, "LOAD 3");
            axi_write(A_CTRL, 32'h0000_0001, 4'b1111, 0, 0);
            t0 = last_eff_edge;
            wait_until_edge(t0 + 6);
            check(!irq, "irq masked while IE is 0");
            read_expect(A_STATUS, 32'd1, OKAY, "EXPIRED set with IE 0");
            read_expect(A_CTRL, 32'd0, OKAY, "EN cleared with IE 0");
            r0 = irq_rises;
            axi_write(A_CTRL, 32'h0000_0002, 4'b1111, 0, 0);
            t1 = last_eff_edge;
            check_eq(irq_rises - r0, 1, "irq rises when IE is written 1");
            check_eq(irq_rise_edge, t1, "irq rises at once on the IE write");
            check(irq, "irq high with IE and EXPIRED");
            read_expect(A_COUNT, 32'd0, OKAY, "IE write does not start a count");
            write_expect(A_CTRL, 32'h0000_0000, 4'b1111, 0, 0, OKAY, "IE written 0");
            check(!irq, "irq drops when IE is written 0");
            read_expect(A_STATUS, 32'd1, OKAY, "EXPIRED kept while IE is 0");
            write_expect(A_STATUS, 32'h0000_0001, 4'b1111, 0, 0, OKAY, "STATUS clear");

            // --- Periodic, timed over several periods; clear on a count end ---
            write_expect(A_LOAD, 32'd10, 4'b1111, 0, 0, OKAY, "LOAD 10");
            r0 = irq_rises;
            axi_write(A_CTRL, 32'h0000_0007, 4'b1111, 0, 0);
            t0 = last_eff_edge;
            wait_until_edge(t0 + 12);
            check_eq(irq_rises - r0, 1, "first periodic expiry");
            check_eq(irq_rise_edge, t0 + 10, "first period ends on edge E+10");
            read_expect(A_CTRL, 32'h0000_0007, OKAY, "EN stays 1 in periodic mode");
            write_expect(A_STATUS, 32'h0000_0001, 4'b1111, 0, 0, OKAY, "STATUS clear");
            check(!irq, "irq drops on clear in periodic mode");
            wait_until_edge(t0 + 19);
            axi_write(A_STATUS, 32'h0000_0001, 4'b1111, 0, 0);
            check_eq(last_eff_edge, t0 + 20, "clear lands on the count-end edge");
            wait_until_edge(t0 + 22);
            check_eq(irq_rises - r0, 2, "count end beats a clear");
            check_eq(irq_rise_edge, t0 + 20, "second period ends on edge E+20");
            read_expect(A_STATUS, 32'd1, OKAY, "EXPIRED kept over a same-edge clear");
            write_expect(A_STATUS, 32'h0000_0001, 4'b1111, 0, 0, OKAY, "STATUS clear");
            check(!irq, "irq drops after clear");
            wait_until_edge(t0 + 32);
            check_eq(irq_rises - r0, 3, "third periodic expiry");
            check_eq(irq_rise_edge, t0 + 30, "third period ends on edge E+30");
            write_expect(A_STATUS, 32'h0000_0001, 4'b1111, 0, 0, OKAY, "STATUS clear");

            // --- Stop freezes COUNT ---
            wait_until_edge(t0 + 34);
            write_expect(A_CTRL, 32'h0000_0004, 4'b1111, 0, 0, OKAY, "stop: EN 0, MODE 1");
            axi_read(A_COUNT, 0);
            cnt_a = last_rdata;
            check(cnt_a != 32'd0, "COUNT nonzero after a mid-count stop");
            wait_until_edge(t0 + 60);
            read_expect(A_COUNT, cnt_a, OKAY, "COUNT frozen while stopped");
            read_expect(A_STATUS, 32'd0, OKAY, "no count ends while stopped");
            read_expect(A_CTRL, 32'h0000_0004, OKAY, "CTRL after stop");
            check_eq(irq_rises - r0, 3, "no interrupt while stopped");

            // --- Restart mid-count (start also reloads from a stopped COUNT) ---
            write_expect(A_LOAD, 32'd20, 4'b1111, 0, 0, OKAY, "LOAD 20");
            r0 = irq_rises;
            axi_write(A_CTRL, 32'h0000_0003, 4'b1111, 0, 0);
            t0 = last_eff_edge;
            wait_until_edge(t0 + 9);
            axi_write(A_CTRL, 32'h0000_0003, 4'b1111, 0, 0);
            t1 = last_eff_edge;
            wait_until_edge(t0 + 22);
            check_eq(irq_rises - r0, 0, "no expiry at the original end");
            wait_until_edge(t1 + 22);
            check_eq(irq_rises - r0, 1, "one expiry after restart");
            check_eq(irq_rise_edge, t1 + 20, "restart counts LOAD from the restart");
            read_expect(A_CTRL, 32'h0000_0002, OKAY, "EN clears after restarted count");
            write_expect(A_STATUS, 32'h0000_0001, 4'b1111, 0, 0, OKAY, "STATUS clear");

            // --- CTRL start landing on a count-end edge: the write wins ---
            write_expect(A_LOAD, 32'd8, 4'b1111, 0, 0, OKAY, "LOAD 8");
            r0 = irq_rises;
            axi_write(A_CTRL, 32'h0000_0003, 4'b1111, 0, 0);
            t0 = last_eff_edge;
            wait_until_edge(t0 + 7);
            axi_write(A_CTRL, 32'h0000_0003, 4'b1111, 0, 0);
            check_eq(last_eff_edge, t0 + 8, "CTRL start lands on the count-end edge");
            wait_until_edge(t0 + 10);
            check_eq(irq_rises - r0, 1, "expiry still set on a same-edge start");
            check_eq(irq_rise_edge, t0 + 8, "count ends on edge E+8");
            read_expect(A_CTRL, 32'h0000_0003, OKAY, "same-edge start keeps EN 1");
            write_expect(A_STATUS, 32'h0000_0001, 4'b1111, 0, 0, OKAY, "STATUS clear");
            check(!irq, "irq drops after clear");
            wait_until_edge(t0 + 18);
            check_eq(irq_rises - r0, 2, "restarted count expires");
            check_eq(irq_rise_edge, t0 + 16, "restarted count ends on edge E+16");
            read_expect(A_CTRL, 32'h0000_0002, OKAY, "EN clears after restarted count");
            write_expect(A_STATUS, 32'h0000_0001, 4'b1111, 0, 0, OKAY, "STATUS clear");

            // --- Reset during a count, with a held write address ---
            write_expect(A_LOAD, 32'd40, 4'b1111, 0, 0, OKAY, "LOAD 40");
            axi_write(A_CTRL, 32'h0000_0007, 4'b1111, 0, 0);
            t0 = last_eff_edge;
            wait_until_edge(t0 + 15);
            awaddr  = A_LOAD;
            awvalid = 1'b1;
            @(negedge clk);
            awvalid = 1'b0;
            check(!awready, "write address held before reset");
            aresetn = 1'b0;
            @(negedge clk);
            @(negedge clk);
            aresetn = 1'b1;
            @(negedge clk);
            check(awready && wready && arready, "reset clears held requests");
            check(!bvalid && !rvalid, "reset drops BVALID and RVALID");
            check(!irq, "irq low after reset during a count");
            read_expect(A_CTRL,   32'd0, OKAY, "CTRL reset during a count");
            read_expect(A_LOAD,   32'd0, OKAY, "LOAD reset during a count");
            read_expect(A_COUNT,  32'd0, OKAY, "COUNT reset during a count");
            read_expect(A_STATUS, 32'd0, OKAY, "STATUS reset during a count");
            r0 = irq_rises;
            repeat (60) @(negedge clk);
            check_eq(irq_rises - r0, 0, "no interrupt after reset");
            read_expect(A_STATUS, 32'd0, OKAY, "no expiry after reset");
            write_expect(A_LOAD, 32'h0000_00A5, 4'b1111, 2, 0, OKAY, "write after reset");
            read_expect(A_LOAD, 32'h0000_00A5, OKAY, "LOAD written after reset");
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = {(8*64){1'b0}};
        do_reset(1'b0);
        run_lane;
        do_reset(1'b1);
        run_lane;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // Watchdog: a hang still ends with a verdict, counted as a failure.
    initial begin
        #1000000;
        failed = failed + 1;
        $error("watchdog timeout");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
